const j = $input.first().json;
const sesion = String(j.sessionId || 'sin-sesion');
const texto = String(j.chatInput || '').trim().slice(0, 1000);
const sd = $getWorkflowStaticData('global');
const hoy = DateTime.now().setZone('Atlantic/Canary').toFormat('yyyy-MM-dd');
if (sd.dia !== hoy) { sd.dia = hoy; sd.totalHoy = 0; sd.sesiones = {}; }
sd.sesiones = sd.sesiones || {};
const nuevaSesion = !sd.sesiones[sesion];
sd.sesiones[sesion] = (sd.sesiones[sesion] || 0) + 1;
sd.totalHoy = (sd.totalHoy || 0) + 1;
const LIMITE_SESION = 25, LIMITE_DIA = 400;
const dentro = sd.sesiones[sesion] <= LIMITE_SESION && sd.totalHoy <= LIMITE_DIA && texto.length > 0;
return [{ json: { sesion, texto, nuevaSesion, dentro, inicio: Date.now() } }];

const ocupados = new Set($input.all().map(i => String(i.json.fecha_hora || '').trim()).filter(Boolean));
const horas = [9, 10, 11, 12, 13, 16, 17];
const huecos = [];
let d = DateTime.now().setZone('Atlantic/Canary').startOf('day').plus({ days: 1 });
while (huecos.length < 10) {
  if (d.weekday <= 5) {
    for (const h of horas) {
      const t = d.set({ hour: h, minute: 0 });
      const clave = t.toFormat('yyyy-MM-dd HH:mm');
      if (!ocupados.has(clave)) huecos.push({ clave, texto: t.setLocale('es').toFormat("cccc d 'de' LLLL, HH:mm") });
      if (huecos.length >= 10) break;
    }
  }
  d = d.plus({ days: 1 });
}
return [{ json: { huecos, lista: huecos.map(h => `- ${h.clave} (${h.texto})`).join('\n'), reservas: ocupados.size } }];

const raw = $input.first().json.output;
let o = null;
if (raw && typeof raw === 'object') o = raw;
else if (typeof raw === 'string') {
  const s = raw.replace(/```json|```/g, '');
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) { try { o = JSON.parse(s.slice(i, j + 1)); } catch (e) {} }
  if (!o && s.trim()) o = { respuesta: s.trim(), intencion: 'otro' };
}
o = o || {};
let respuesta = String(o.respuesta || '').trim() || 'Perdona, se me ha liado un poco 😅 ¿Me lo cuentas de otra forma?';
if (/\d[\d.,]*\s*(€|euros?\b|eur\b)|€\s*\d/i.test(respuesta) || /━━|FORMATO DE SALIDA/.test(respuesta)) {
  respuesta = 'El presupuesto lo preparamos siempre después de una visita técnica gratuita 😊 ¿Te busco un hueco?';
}
const acc = o.accion || {};
const huecos = $('Calcular huecos libres').first().json.huecos || [];
const hueco = huecos.find(h => h.clave === String(acc.hueco || '').trim());
const quiereReservar = acc.tipo === 'reservar';
const reservar = quiereReservar && !!hueco;
if (quiereReservar && !hueco) {
  respuesta = 'Vaya, ese hueco ya no está libre. ' + (huecos.length ? `¿Te va bien el ${huecos[0].texto} o el ${(huecos[1] || huecos[0]).texto}?` : '¿Te aviso cuando haya disponibilidad?');
}
return [{ json: {
  respuesta, reservar, reservaRechazada: quiereReservar && !hueco,
  intencion: o.intencion || 'otro',
  datos: o.datos_cliente || {},
  reserva: reservar ? { clave: hueco.clave, texto: hueco.texto, nombre: String(acc.nombre || (o.datos_cliente || {}).nombre || '').trim(), motivo: String(acc.motivo || (o.datos_cliente || {}).reforma || '').trim() } : null
} }];

const r = $('Interpretar respuesta').first().json;
let guardada = false;
try { guardada = r.reservar && !$('Guardar reserva').first().json.error; } catch (e) { guardada = false; }
const nombres = { saludo: 'saludo', informacion: 'pide información', presupuesto: 'quiere presupuesto', reservar: 'quiere reservar', pregunta_sobre_geor: 'pregunta cómo funciona GEOR', otro: 'otro' };
const lineas = [];
lineas.push(`🧠 Intención detectada: *${nombres[r.intencion] || r.intencion}*`);
const d = r.datos || {};
const datos = [d.nombre && `nombre = ${d.nombre}`, d.reforma && `reforma = ${d.reforma}`].filter(Boolean);
if (datos.length) lineas.push(`🗂️ Datos extraídos del mensaje: ${datos.join(' · ')}`);
if (r.intencion === 'reservar' || r.reservar || r.reservaRechazada) lineas.push(`📅 Agenda consultada en tiempo real (${$('Calcular huecos libres').first().json.huecos.length} huecos libres)`);
if (r.reservar && guardada) lineas.push(`✅ Reserva guardada: ${r.reserva.texto} · ${r.reserva.nombre || 'sin nombre'}`);
if (r.reservar && !guardada) lineas.push('⚠️ No se pudo guardar la reserva (se reintentará)');
if (r.reservaRechazada) lineas.push('⛔ Hueco no disponible: se proponen otros');
if (r.reservar && guardada) lineas.push('🔔 En un negocio real, aquí el equipo recibe un aviso por WhatsApp');
let enlaces = '';
if (r.intencion === 'pregunta_sobre_geor') {
  enlaces = '\n\n🔗 **Conoce a quien me ha construido**\n\n- Noelia Soto · LinkedIn: https://www.linkedin.com/in/noeliasotovega\n- GitHub: https://github.com/Noelia-Geor\n- GeorLuna, su producto SaaS para autónomos: https://georluna.com';
  lineas.push('🔗 Enlaces a los proyectos de Noelia añadidos');
}
const seg = ((Date.now() - $('Control de uso').first().json.inicio) / 1000).toFixed(1);
lineas.push(`⏱️ Procesado en ${seg} s · n8n + gpt-4o-mini`);
const output = `${r.respuesta}${enlaces}\n\n---\n\n⚙️ **Detrás de escena**\n\n${lineas.map(l => '- ' + l).join('\n')}`;
return [{ json: { output } }];
